import sys

def findMaximumNum(s, k):
    n = len(s)
    if k == 0:
        return s

    digits = list(s)
    max_num = s

    def backtrack(current_digits, swaps_left):
        nonlocal max_num
        current_str = ''.join(current_digits)
        if current_str > max_num:
            max_num = current_str

        if swaps_left == 0:
            return

        for i in range(n - 1):
            for j in range(i + 1, n):
                if current_digits[i] < current_digits[j]:
                    current_digits[i], current_digits[j] = current_digits[j], current_digits[i]
                    backtrack(current_digits, swaps_left - 1)
                    current_digits[i], current_digits[j] = current_digits[j],current_digits[i]

    backtrack(digits, k)
    return max_num

def main():
    lines = sys.stdin.read().strip().splitlines()
    if not lines:
        return
    k = int(lines[0].strip())
    s = lines[1].strip()
    result = findMaximumNum(s, k)
    print(result)

if __name__ == "__main__":
    main()
